globalThis.makeSubjectEdition = function (meta, rows) {
  const {subject, year, grade, contest, letters, tasksFile, answersFile, language} = meta;
  const folder = 'assets/' + subject + '/' + year + '/';
  const grades = grade.split('-').map(Number);
  const lessons = rows.map(row => {
    const {title, question, choices, figure, figures, optionFigures, steps, context, audio, numericAnswer} = row;
    const condition = figures?.length ? {items: figures} : figure;
    const options = choices.map((text, i) => {
      const image = optionFigures?.[i];
      if (!image) return {text};
      return {text: row.showOptionText ? text : '', image: image.src,
        description: row.showOptionText ? text + '. ' + image.alt : image.alt,
        ...(image.detailSrc ? {detailSrc: image.detailSrc} : {}),
        pixelWidth: image.width, pixelHeight: image.height};
    });
    return {
      title, question, choices, language, context, guided: true, hideIntroText: true,
      skill: contest, answer: row.answer ?? null,
      points: row.points ?? meta.points,
      ...(row.adaptation ? {questionNote: row.adaptation} : {}),
      ...(row.number ? {number: row.number} : {}),
      ...(Number.isInteger(numericAnswer) ? {numericAnswer} : {}),
      ...(audio ? {audio: folder + (meta.listeningFile ?? 'listening.mp3')} : {}),
      ...(condition || optionFigures ? {choiceLayout: {condition, options},
        choiceImages: options.map(option => option.image),
        ...(condition?.src ? {conditionImage: condition.src, conditionAlt: condition.alt} : {})} : {}),
      steps: [
        ['Выбор', 'Условие задачи', ''],
        ...steps.map((explanation, index) => index === steps.length - 1
          ? ['Проверка', 'Проверка', explanation]
          : [index ? 'Шаг ' + (index + 1) : 'Первый шаг', 'Рассуждение', explanation]),
        ['Ответ', 'Ответ', ''],
      ],
    };
  });
  for (const group of meta.matchingGroups ?? []) {
    const parts = lessons.slice(group.start - 1, group.start - 1 + group.count);
    if (parts.length !== group.count || parts.some(part => !part.conditionImage ||
        JSON.stringify(part.choices) !== JSON.stringify(parts[0].choices))) throw new Error('Incomplete matching group ' + group.title);
    const steps = [
      ['Выбор', 'Условие задачи', ''],
      ...parts.map((part, index) => ['Рисунок ' + (index + 1), part.title,
        part.steps.slice(1, -1).map(step => step[2]).join(' ')]),
      ['Ответ', 'Все пары', ''],
    ];
    for (const part of parts) Object.assign(part, {matching: group, title: group.title, question: group.question, steps});
  }
  return {
    id: [year, subject, meta.session, grade, meta.editionSuffix].filter(Boolean).join('-'), year, grades,
    label: grades.join('–') + (grades.length === 1 ? ' класс' : ' классы') + (meta.sessionTitle ? ' · ' + meta.sessionTitle : '') + (meta.editionLabel ? ' · ' + meta.editionLabel : ''),
    ...(meta.sections ? {sections: meta.sections} : {}),
    ...(meta.titleLanguage ? {titleLanguage: meta.titleLanguage} : {}),
    subject, answerLetters: [...letters], sources: {
      contest, tasksUrl: folder + tasksFile, answersUrl: folder + answersFile,
      ...(meta.reviewedKey ? {reviewedKey: true} : {}),
    },
    lessons, scenes: lessons.map(() => () => ''),
  };
};

const edition = globalThis.makeSubjectEdition({"subject":"kit","year":2022,"grade":"4-5","contest":"КИТ","letters":"АБВГ","count":21,"language":"ru","points":3,"tasksFile":"4-5.pdf","answersFile":"reviewed-4-5.pdf","sections":[{"start":1,"title":"2 балла · № 1–8"},{"start":9,"title":"3 балла · № 9–16"},{"start":17,"title":"4 балла · № 17–18"},{"start":19,"title":"Числовой ответ · № 19–21"}],"reviewedKey":true}, [{"title":"Латинское слово","question":"Cursiva с латыни переводится как «беглый». Переведи с латинского языка слово cursor.","choices":["бегун","красный","сорить","курица"],"points":2,"steps":["У слов cursiva и cursor общий латинский корень, связанный с бегом и движением.","Cursor — тот, кто бежит, то есть бегун. Компьютерный курсор тоже перемещается по экрану."],"answer":0},{"title":"Время на часах","question":"Какие часы показывают 15:40?","choices":["Часы А","Часы Б","Часы В","Часы Г"],"points":2,"steps":["15:40 — это три часа сорок минут дня. При 40 минутах длинная минутная стрелка указывает на 8, потому что 8 × 5 = 40.","Короткая стрелка должна стоять между 3 и 4, ближе к 4. Так стрелки стоят на часах В."],"answer":2,"optionFigures":[{"src":"assets/kit/2022/4-5-02-a.webp","alt":"Минутная стрелка у 4, часовая между 8 и 9","width":134,"height":136},{"src":"assets/kit/2022/4-5-02-b.webp","alt":"Минутная стрелка у 12, часовая у 10","width":134,"height":134},{"src":"assets/kit/2022/4-5-02-c.webp","alt":"Минутная стрелка у 8, часовая между 3 и 4","width":142,"height":138},{"src":"assets/kit/2022/4-5-02-d.webp","alt":"Минутная стрелка у 6, часовая между 1 и 2","width":138,"height":138}]},{"title":"Очертания замка","question":"Вдалеке видны очертания замка. Какой из фрагментов не принадлежит очертаниям замка?","choices":["Фрагмент А","Фрагмент Б","Фрагмент В","Фрагмент Г"],"points":2,"steps":["В середине после большого пика есть ступень вниз и дуга, как в Б. Спуск с дуги к высокой башне и ступень справа от башни дают А.","Слева первый острый пик переходит в горизонтальную ступень, как в В. Зигзаг, переходящий прямо в высокий плоский верх, как в Г, в контуре отсутствует."],"answer":3,"figure":{"src":"assets/kit/2022/4-5-03.webp","alt":"Слева направо дуга, острый пик, ступень, высокий острый пик, ступень, дуга, прямоугольная башня, узкий острый пик и две дуги.","width":540,"height":100},"optionFigures":[{"src":"assets/kit/2022/4-5-03-a.webp","alt":"Спуск с дуги, затем прямоугольная башня","width":110,"height":96},{"src":"assets/kit/2022/4-5-03-b.webp","alt":"Ступень вниз и дуга","width":106,"height":82},{"src":"assets/kit/2022/4-5-03-c.webp","alt":"Острый пик и ступень вверх","width":104,"height":84},{"src":"assets/kit/2022/4-5-03-d.webp","alt":"Зигзаг, сразу переходящий в плоскую башню","width":112,"height":84}]},{"title":"Зачем скрывают пароль","question":"При авторизации в социальных сетях предлагается ввести логин и пароль. Пароль отображается в виде точек или звёздочек. Зачем?","choices":["так удобнее","для обеспечения безопасности","чтобы запутать","точки или звёздочки — это и есть пароль"],"points":2,"steps":["Точки показывают, что символы введены, но скрывают сами буквы и цифры.","Так сложнее подсмотреть пароль через плечо или увидеть его на записи экрана. Поэтому ответ Б — для обеспечения безопасности."],"answer":1},{"title":"Устройства в паре","question":"Какое устройство обычно используют парами?","choices":["Ноутбук","Принтер","Мышь","Колонка"],"points":2,"steps":["Ноутбуком, принтером и мышью обычно пользуются по отдельности.","Колонки часто ставят слева и справа. Две колонки позволяют слышать разные каналы стереозвука."],"answer":3,"optionFigures":[{"src":"assets/kit/2022/4-5-05-a.webp","alt":"Ноутбук с открытой крышкой","width":162,"height":124},{"src":"assets/kit/2022/4-5-05-b.webp","alt":"Принтер","width":160,"height":114},{"src":"assets/kit/2022/4-5-05-c.webp","alt":"Компьютерная мышь","width":120,"height":106},{"src":"assets/kit/2022/4-5-05-d.webp","alt":"Одна акустическая колонка","width":82,"height":124}]},{"title":"Общие буквы","question":"Сколько одинаковых букв в словах кот и крот?","choices":["1","2","3","4"],"points":2,"steps":["В «кот» есть К, О и Т. В «крот» к этим трём буквам добавлена Р.","Совпадают К, О, Т. Это три буквы."],"answer":2},{"title":"Почтальон на маршруте","question":"Почтальон разносит почту. Что он принесёт в квартиру 2?","choices":["письмо","открытку","журнал","газету"],"points":2,"steps":["Найди квартиру 2 справа. В неё приходит наклонная стрелка сверху слева.","Эта стрелка отходит от «письмо», как и горизонтальная стрелка к квартире 1. В квартиру 2 принесут письмо."],"answer":0,"figure":{"src":"assets/kit/2022/4-5-07.webp","alt":"Письмо стрелками соединено с квартирами 1 и 2, открытка — с квартирой 3, журнал — с квартирой 3, газета — с квартирой 4.","width":240,"height":96}},{"title":"Маршрут через города","question":"Выбери туристическую карту, по которой можно пройти от A до F, посетив при этом наибольшее количество городов.","choices":["Карта А","Карта Б","Карта В","Карта Г"],"points":2,"steps":["На карте А из A нельзя выйти по стрелкам. На карте Б путь из A через B заканчивается в C.","На карте В до F можно добраться через B и C, посетив четыре города. На карте Г маршрут A → D → E → B → C → F охватывает все шесть."],"answer":3,"optionFigures":[{"src":"assets/kit/2022/4-5-08-a.webp","alt":"B → A, B → C, B → E, C → F, F → E, E → D, D → A","width":160,"height":108},{"src":"assets/kit/2022/4-5-08-b.webp","alt":"A → B → C, E → D, E → F, D → A, E → B, F → C","width":158,"height":108},{"src":"assets/kit/2022/4-5-08-c.webp","alt":"A → B → C, A → D, B → E, C → F, F → E, E → D","width":158,"height":108},{"src":"assets/kit/2022/4-5-08-d.webp","alt":"A → B → C, A → D, E → B, C → F, D → E → F","width":158,"height":108}]},{"title":"Лампа первого компьютера","question":"Как выглядела лампа лампового ЭВМ?","choices":["Радиолампа","Энергосберегающая лампа","Лампа накаливания","Керосиновая лампа"],"points":3,"steps":["В ламповой ЭВМ электронные лампы переключали электрические сигналы. Освещать комнату им не требовалось.","На фото А радиолампа со штырьками, которые соединяют её с электрической схемой. Остальные три лампы служат для освещения."],"answer":0,"optionFigures":[{"src":"assets/kit/2022/4-5-09-a.webp","alt":"Радиолампа со штырьками","width":78,"height":164},{"src":"assets/kit/2022/4-5-09-b.webp","alt":"Лампа со спиральной люминесцентной трубкой","width":80,"height":164},{"src":"assets/kit/2022/4-5-09-c.webp","alt":"Лампа накаливания","width":98,"height":162},{"src":"assets/kit/2022/4-5-09-d.webp","alt":"Керосиновая лампа","width":60,"height":162}]},{"title":"Имя учёного","question":"Какой термин связан с именем учёного, изображённого справа?","choices":["модем","цикл","алгоритм","компьютер"],"points":3,"steps":["На марке подписано имя Мухаммада аль-Хорезми. Его трактат познакомил европейских читателей с вычислениями в позиционной системе.","Латинизированная форма имени аль-Хорезми дала слово «алгоритм». Сейчас так называют порядок действий для решения задачи."],"answer":2,"figure":{"src":"assets/kit/2022/4-5-10.webp","alt":"Марка с портретом и подписью «Мухаммад аль-Хорезми».","width":162,"height":224}},{"title":"Египетская монета","question":"Определи номинал (стоимость) египетской монеты. На рисунке показано соответствие египетских цифр цифрам от 0 до 9.","choices":["10","20","25","50"],"points":3,"steps":["Найди первый знак на монете в таблице. ٢ означает 2. Следующий знак ٥ означает 5.","Цифры в числе читают слева направо. Получается 25."],"answer":2,"figure":{"src":"assets/kit/2022/4-5-11.webp","alt":"Таблица: 0 — ٠, 1 — ١, 2 — ٢, 3 — ٣, 4 — ٤, 5 — ٥, 6 — ٦, 7 — ٧, 8 — ٨, 9 — ٩. В центре монеты слева ٢, справа ٥.","width":582,"height":230}},{"title":"Как заплатить за ручку","question":"У Васи много монет по 1 рублю и по 5 рублей. Сколькими способами он может заплатить за ручку ровно 6 рублей?","choices":["1","2","3","4"],"points":3,"steps":["Если взять одну пятирублёвую монету, останется добавить 1 рубль. Две пятирублёвые уже дают больше 6.","Без пятирублёвых монет нужны шесть монет по рублю. Итого два способа."],"answer":1},{"title":"Старший из братьев","question":"В семье пять братьев, про которых известно, что Вася старше Коли, Саша младше Серёжи, Вася старше Володи и Серёжа младше Володи. Старшего брата в семье зовут…","choices":["Вася","Володя","Коля","Саша"],"points":3,"steps":["По данным условия Вася старше Володи, Володя старше Серёжи, а Серёжа старше Саши.","Мы также знаем, что Вася старше Коли. Он старше каждого из четырёх братьев."],"answer":0},{"title":"Что измеряет кегль","question":"Бриллиант, диамант (то есть алмаз), перл (то есть жемчужина), агат, миньон (то есть милый, крошечный) — это названия разных кеглей. А кегль — это размер…","choices":["экрана монитора","корпуса компьютера","оперативной памяти компьютера","букв в текстовых редакторах"],"points":3,"steps":["В типографике маленькие размеры шрифта получали свои названия, в том числе «бриллиант» и «миньон».","Кегль выражают в типографских пунктах. В текстовом редакторе он задаёт размер шрифта, поэтому выбираем Г."],"answer":3},{"title":"Робот убирает комнату","question":"Робот-пылесос убирает комнату по спирали. На каждом шаге он пробует соседние клетки в таком порядке: слева по ходу движения, прямо и справа. Он переходит в первую свободную клетку, которую ещё не убирал, и поворачивается в сторону движения. Если таких клеток нет, он останавливается. Сколько свободных клеток робот не уберёт, если начнёт с поля А12 и поедет вправо?","choices":["0","8","12","4"],"points":3,"steps":["Пройди из А12 вправо до С12, затем вниз до С1 и влево до О1. Дальше робот огибает чёрное препятствие, оставляя его слева, и доходит до А1.","От А1 он поднимается до А11 и начинает следующий виток, оставляя прежний путь слева. На каждом шаге сначала проверь клетку слева, потом клетку прямо и наконец справа.","Последний ход ведёт в О9, где не осталось свободного соседа. Свободными остались четыре клетки в ряду 7 и четыре в ряду 8, в столбцах Г, Д, Е и Ж. Всего 8."],"answer":1,"figure":{"src":"assets/kit/2022/4-5-15.webp","alt":"Сетка из 17 столбцов А, Б, В, Г, Д, Е, Ж, З, И, К, Л, М, Н, О, П, Р, С и 12 рядов, пронумерованных снизу вверх. Препятствие занимает столбцы Д–Н в рядах 1–3 и Л–Н в рядах 4–5.","width":440,"height":316},"reviewedEdition":true},{"title":"Четыре шага алгоритма","question":"Какое число получится, если, начав с числа 1, четыре раза применить алгоритм: если текущее число меньше 6, то прибавить к нему 4, в противном случае отнять от него 1?","choices":["7","2","12","17"],"points":3,"steps":["Число 1 меньше 6, поэтому получаем 1 + 4 = 5. Это снова меньше 6, на втором шаге получаем 5 + 4 = 9.","Числа 9 и 8 не меньше 6. На третьем и четвёртом шагах вычитаем по 1. Получаем 9 → 8 → 7."],"answer":0},{"title":"Цепочка замен букв","question":"Каждый из четырёх школьников, играя в глухой телефон, в передаваемом слове менял одну букву на соседнюю по алфавиту. На выходе получилось слово пень. Каким могло быть исходное слово, предложенное им?","choices":["тень","лень","конь","пена"],"points":4,"steps":["В слове «лень» первую букву можно сдвинуть четыре раза: Л → М → Н → О → П. Остальные буквы остаются прежними.","От Т до П три шага. Если потратить лишний шаг, пришлось бы сдвинуть ещё одну букву или уйти с нужного места. Вернуться сюда можно лишь за чётное число лишних шагов.","От К до П требуется уже пять шагов, а в «конь» нужно изменить и вторую букву. В слове «пена» А и Ь тоже разделяют больше четырёх позиций."],"answer":1},{"title":"Экран без диагоналей","question":"Каждая ячейка экрана калькулятора отображает одну цифру при помощи трёх горизонтальных, четырёх вертикальных и двух диагональных перекладин, как показано на рисунке. Сколько всего различных цифр можно определить в ячейке однозначно, если перегорят обе диагональные перекладины этой ячейки?","choices":["6","7","8","10"],"points":4,"steps":["Убери диагональные чёрные штрихи и сгруппируй цифры по горизонтальным перекладинам. Совпадают группы 0 и 2, 3 и 9, 5 и 8. У цифр 1, 4, 6 и 7 свой набор горизонталей.","В каждой паре есть различие по вертикали. У 0 горят все четыре вертикали, у 2 — только верхняя правая. У 9 есть верхняя левая вертикаль, которой нет у 3. У 8 есть нижняя левая вертикаль, которой нет у 5.","Оставшихся штрихов хватит, чтобы узнать любую из десяти цифр."],"answer":3,"figure":{"src":"assets/kit/2022/display-segments.svg","alt":"Десять наборов от 0 до 9. В каждом тонкие линии обозначают выключенные, толстые — включённые перекладины. Потухшие диагонали мысленно уберите.","width":393,"height":63}},{"title":"Снятие денег в банкомате","question":"На счёте Ка-Ака было 2000 пиастров. Он дважды снял одну и ту же сумму, набирая её в банкомате как #, æ, Ω. Эти три знака обозначают разные цифры десятичной системы планеты Туя. Попытка снять ещё 27 пиастров не удалась, потому что денег осталось меньше 27. Какую цифру обозначает Ω?","choices":[],"points":4,"steps":["Два одинаковых снятия прошли, поэтому одна сумма не больше 1000. После них осталось меньше 27. Значит, всего сняли больше 1973 пиастров, а каждое снятие составляло не меньше 987.","Сумму ввели тремя разными цифрами, поэтому 1000 отпадает. Среди чисел от 987 до 999 только 987 состоит из трёх разных цифр.","Последний знак Ω обозначает 7. После двух снятий остаётся 2000 − 2 × 987 = 26, так что снять ещё 27 нельзя."],"numericAnswer":7,"reviewedEdition":true},{"title":"Кто говорит правду","question":"За столом переговоров собрались 6 человек. Часть из них говорит только правду, а часть — всегда лжёт. В результате каждый заявил остальным: «Все вы — лжецы». Сколько человек, говорящих правду, сидит за столом?","choices":[],"points":4,"steps":["Если бы все лгали, у каждого из шести фраза «Все вы — лжецы» была бы верной. Значит, кто-то говорит правду.","Как только один говорит правду, остальные пять по его верному утверждению лгут. Их фраза действительно неверна: среди остальных есть тот, кто говорит правду."],"numericAnswer":1},{"title":"Кольца на трёх стержнях","question":"Даны три различных по размеру кольца и три стержня. За один ход можно перемещать одно кольцо с одного стержня на другой. При этом можно ставить только меньшее кольцо на большее. Сначала башня построена на одном из стержней в порядке от большего кольца внизу до меньшего наверху. За какое наименьшее количество ходов можно переместить кольца с одного стержня на другой?","choices":[],"points":4,"steps":["Чтобы передвинуть большое кольцо на свободный стержень, сначала собери два маленьких на другом стержне. Для этого необходимы три хода: малое в сторону, среднее на нужный стержень, малое поверх среднего.","Перенеси большое кольцо одним ходом. Затем теми же тремя ходами собери два маленьких на большом.","Меньше невозможно: перед ходом большого надо переместить оба маленьких, а после его хода оба нужно снова переставить друг на друга. Эти операции стоят по три хода. Итого 3 + 1 + 3 = 7."],"numericAnswer":7}]);
